NATIVE_CHAT_HTML = r"""<!doctype html>
<html lang="zh-Hant">
<head>
<meta charset="utf-8">
<meta name="viewport" content="width=device-width,initial-scale=1">
<title>E4B Core</title>
<style>
:root{color-scheme:dark;font-family:system-ui,"Microsoft JhengHei",sans-serif;background:#181818;color:#ececec;font-size:14px}*{box-sizing:border-box}body{margin:0}button{border:0;border-radius:9px;background:#333;color:#eee;padding:9px 13px;font:inherit;cursor:pointer}button:disabled{opacity:.5;cursor:default}button:focus-visible,select:focus-visible{outline:2px solid #aaa;outline-offset:3px}.secondary{background:#303030}.danger{background:#333}main{height:100dvh;margin-left:250px;display:grid;grid-template-rows:58px minmax(0,1fr) auto auto}header{display:flex;justify-content:space-between;align-items:center;padding:0 26px;border-bottom:1px solid #2a2a2a;gap:12px}h1{font-size:14px;font-weight:500;margin:0}.sub{font-size:11px;color:#999}.actions{display:flex;gap:8px}.actions button{font-size:12px}#sidebar{position:fixed;inset:0 auto 0 0;width:250px;background:#202020;border-right:1px solid #303030;padding:22px 14px;display:flex;flex-direction:column;gap:10px}#sidebar h2{font-size:15px;margin:0 8px 20px}.nav-title{font-size:11px;color:#929292;margin:20px 10px 4px;letter-spacing:1px}#threads{display:flex;flex-direction:column;overflow:auto;gap:3px}.thread{background:transparent;color:#c7c7c7;padding:11px 12px;text-align:left;border-radius:8px;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}.thread.active,.thread:hover{background:#343434;color:white}#privacy{margin-top:auto;color:#888;font-size:11px;padding:12px;line-height:1.7}#chat{min-height:0;overflow:auto;display:flex;flex-direction:column;padding:28px max(24px,calc((100% - 820px)/2));gap:22px}.msg{white-space:pre-wrap;line-height:1.65;padding:4px 0}.user{align-self:flex-end;max-width:80%;background:#303030;padding:12px 18px;border-radius:18px}.assistant{width:100%}.assistant pre{background:#252525;border:1px solid #383838;padding:15px;border-radius:12px;overflow:auto;white-space:pre}.assistant code{font:12px/1.7 Consolas,monospace}.assistant h2{font-size:20px}.assistant h3{font-size:17px}.notice{align-self:center;color:#999;font-size:12px;white-space:pre-wrap;max-width:90%}#welcome{text-align:center;margin:auto 0;color:#999}#welcome h2{font-size:28px;color:#ececec;font-weight:500}#form{display:grid;grid-template-columns:auto 1fr auto auto;gap:8px;margin:12px auto 0;width:min(820px,calc(100% - 48px));background:#262626;border:1px solid #3b3b3b;border-radius:20px;padding:12px;align-items:end}textarea{resize:none;min-height:64px;max-height:180px;border:0;background:transparent;color:inherit;padding:6px;font:inherit;outline:none}#send{height:34px;width:34px;padding:0;border-radius:50%;background:#ddd;color:#171717;font-size:20px}#stop{height:34px;background:#444;padding:0 12px}.controls{order:4;margin:0 auto 20px;width:min(820px,calc(100% - 48px));display:grid;gap:12px;align-items:center;padding:6px 4px;grid-template-columns:auto auto 1fr}.control{display:grid;gap:5px;font-size:12px;color:#aeb9c5}.control>span:not(.control-title),.control-title>span{display:none}.control-title{display:flex;justify-content:flex-end}.toggle{display:flex;align-items:center;gap:7px;height:28px;font-size:12px}.toggle input{width:17px;height:17px}select{height:28px;border:0;border-radius:7px;background:#252525;color:inherit;padding:0 8px;font:inherit}.cwd{min-width:0;display:flex;align-items:center;gap:8px;flex-direction:row-reverse}.cwd input{width:100%;min-width:0;height:28px;background:transparent;border:0;color:#999;font-size:11px}.mini{padding:5px 9px;white-space:nowrap;font-size:12px}.tool-card,.approval-card{border:1px solid #383838;background:#212121;border-radius:12px;padding:12px;width:100%;font-size:12px}.tool-card summary{cursor:pointer;color:#bbb}.tool-card pre,.approval-card pre{white-space:pre-wrap;overflow-wrap:anywhere;max-height:320px;overflow:auto;color:#bbb}.approval-card button{margin:8px 8px 0 0;padding:8px 14px;background:#eee;color:#222}.approval-card .secondary{background:#444;color:#ddd}dialog{width:min(680px,92vw);max-height:78vh;border:1px solid #35404d;border-radius:16px;background:#202020;color:inherit;padding:0}dialog::backdrop{background:#000a}.folder-head{display:flex;align-items:center;justify-content:space-between;padding:14px 16px;border-bottom:1px solid #3b3b3b}.folder-path{padding:11px 16px;color:#aeb9c5;word-break:break-all}.folder-list{display:grid;gap:5px;max-height:48vh;overflow:auto;padding:0 12px 12px}.folder-item{background:#303030;text-align:left;min-height:38px;padding:8px 12px}.folder-actions{display:flex;justify-content:flex-end;gap:8px;padding:12px 16px;border-top:1px solid #3b3b3b}#review{position:fixed;right:0;top:58px;bottom:0;width:min(480px,90vw);padding:20px;background:#202020;border-left:1px solid #444;overflow:auto;z-index:5}#review[hidden]{display:none}#review h2{font-size:16px}#review pre{white-space:pre-wrap;overflow-wrap:anywhere;font:12px/1.7 monospace}#review-close{float:right;padding:8px}#review details{border-bottom:1px solid #444;padding:14px 0}#review summary{overflow-wrap:anywhere;cursor:pointer}.diff-add{color:#8bd49b}.diff-remove{color:#ed9999}@media(max-width:760px){#sidebar{width:180px}main{margin-left:180px}header{padding:0 14px}.actions{gap:4px}.actions button{padding:7px}#chat{padding:20px}#form,.controls{width:calc(100% - 24px)}.controls{grid-template-columns:auto auto}.cwd{grid-column:1/-1}}@media(max-width:520px){#sidebar{width:56px;padding:16px 4px}#sidebar h2{font-size:11px;margin:0 0 10px}.nav-title,#privacy{display:none}#sidebar>button{font-size:0;padding:12px 0}#sidebar>button:before{content:'+';font-size:20px}.thread{padding:8px;font-size:11px}main{margin-left:56px}header .sub{display:none}.actions button{font-size:10px;padding:5px}header{padding:0 8px;gap:4px}.controls{gap:6px}.toggle{gap:4px}}

#attachments{grid-column:1/-1;display:flex;flex-wrap:wrap;gap:6px}#attachments:empty{display:none}.attachment{font-size:11px;border:1px solid #555;padding:5px 9px}#attach{width:30px;height:34px;padding:0;background:transparent;font-size:22px}main.terminal-open{grid-template-rows:58px minmax(0,1fr) 220px auto auto}#terminal-pane{min-height:0;background:#181818;border-block:1px solid #3b3b3b;display:grid;grid-template-rows:auto minmax(0,1fr) auto;padding:8px 18px;gap:5px}#terminal-pane[hidden]{display:none}.terminal-head{display:flex;align-items:center;gap:8px;font-size:11px}.terminal-head strong{margin-right:10px}.terminal-head span{flex:1;min-width:0;overflow:hidden;text-overflow:ellipsis;white-space:nowrap;color:#999}.terminal-head button{font-size:10px;padding:4px 8px}#terminal-output{margin:0;overflow:auto;white-space:pre-wrap;overflow-wrap:anywhere;font:12px/1.6 Consolas,monospace}#terminal-form{display:flex;gap:8px;margin:0;border:0;padding:0}#terminal-command{flex:1;min-width:0;border:1px solid #444;background:#222;color:inherit;border-radius:6px;padding:7px;font:12px Consolas,monospace}#terminal-run{font-size:11px;padding:6px 12px}
#folder-address-form{display:flex;padding:12px 16px;gap:8px}#folder-address{flex:1;min-width:0;padding:8px;background:#292929;color:inherit;border:1px solid #444;border-radius:7px}#branch-label{display:block;font-size:10px}#worktree-create{max-width:130px}
 #folder-dialog[open]{display:flex;flex-direction:column;overflow:hidden}#folder-dialog .folder-head,#folder-address-form,#folder-dialog .folder-actions{flex-shrink:0}#folder-dialog .folder-path{flex-shrink:0;max-height:64px;overflow:auto}#folder-list{flex:1;min-height:0;max-height:none;overflow:auto}#folder-error{margin:0;padding:0 16px 10px;color:#ed9999;max-height:64px;overflow:auto;flex-shrink:0}#folder-error[hidden]{display:none}
</style>
</head>
<body><aside id="sidebar"><h2>E4B</h2><button id="new-thread" class="secondary">＋ 新對話</button><button id="open-project" class="secondary">開啟專案</button><div class="nav-title">專案與對話</div><div id="threads"></div><div id="privacy">本機工作 · 對話只在記憶體<br>關閉頁面後不保留對話</div></aside><main>
<header><div><h1>E4B Core</h1><div class="sub">獨立本機 AI · 對話只留在記憶體</div></div><div class="actions"><button id="save" class="secondary">儲存設定</button><button id="reset" class="secondary">新對話</button><button id="shutdown" class="danger">關閉 E4B</button></div></header>
<section class="controls">
  <label class="control"><span>Thinking effort</span><select id="effort"><option value="off">關閉</option><option value="low">低</option><option value="medium" selected>中</option><option value="high">高</option></select></label>
  <label class="toggle"><input id="agent" type="checkbox" checked>啟用 Agent</label>
  <div class="control cwd" id="cwd-wrap"><span class="control-title"><span>目前 Workspace</span><button id="browse" type="button" class="secondary mini">開啟資料夾</button></span><input id="cwd" type="text" readonly placeholder="尚未開啟資料夾"></div>
</section>
<section id="chat"><div id="welcome"><h2>今天要完成什麼？</h2><p>開啟專案，讓 E4B 讀取、修改與驗證你的工作。</p></div><div class="notice">96K context；Agent 的寫檔、編輯與 Shell 操作會先請你批准</div></section>
<section id="terminal-pane" hidden><div class="terminal-head"><strong>PowerShell</strong><span id="terminal-cwd"></span><button id="terminal-stop" type="button" disabled>停止</button><button id="terminal-clear" type="button">清除</button><button id="terminal-hide" type="button">收起</button></div><pre id="terminal-output" role="log" aria-live="polite"></pre><form id="terminal-form"><input id="terminal-command" aria-label="終端命令" autocomplete="off" placeholder="在專案中執行命令…"><button id="terminal-run">執行</button></form></section>
<form id="form"><div id="attachments"></div><input id="file-input" type="file" multiple hidden accept=".txt,.md,.py,.js,.ts,.tsx,.jsx,.json,.csv,.html,.css,.yaml,.yml,.toml,.xml,.log,.pdf,.docx"><button id="attach" type="button" aria-label="附加檔案">＋</button><textarea id="input" aria-label="工作指令" placeholder="描述工作，或提出問題…" autofocus></textarea><button id="stop" type="button" hidden>停止</button><button id="send" aria-label="送出">↑</button></form>
</main>
<dialog id="folder-dialog"><div class="folder-head"><strong>選擇 Agent 工作目錄</strong><button id="folder-close" class="secondary mini">關閉</button></div><form id="folder-address-form"><input id="folder-address" aria-label="資料夾路徑" placeholder="輸入資料夾路徑"><button>前往</button></form><div id="folder-path" class="folder-path"></div><p id="folder-error" role="alert" hidden></p><div id="folder-list" class="folder-list"></div><div class="folder-actions"><button id="folder-use" disabled>使用這個資料夾</button></div></dialog>
<aside id="review" hidden><button id="review-close">關閉</button><h2>本次修改</h2><p id="review-empty">這個對話尚未修改檔案。</p><div id="review-files"></div></aside>
<script>
const chat=document.querySelector('#chat'),input=document.querySelector('#input'),send=document.querySelector('#send');
const effort=document.querySelector('#effort'),agent=document.querySelector('#agent'),cwd=document.querySelector('#cwd'),cwdWrap=document.querySelector('#cwd-wrap');
const mode=document.createElement('select');mode.id='mode';mode.setAttribute('aria-label','工作模式');for(const [value,label] of [['work','工作'],['plan','規劃']]){const option=document.createElement('option');option.value=value;option.textContent=label;mode.append(option)}document.querySelector('.toggle').append(mode);
const branchLabel=document.createElement('span');branchLabel.id='branch-label';branchLabel.className='sub';document.querySelector('header h1').after(branchLabel);const worktreeButton=document.createElement('button');worktreeButton.id='worktree-create';worktreeButton.textContent='建立 Worktree';worktreeButton.className='mini';worktreeButton.disabled=true;document.querySelector('.cwd').prepend(worktreeButton);
async function refreshWorkspace(){const id=session,path=cwd.value;document.querySelector('header h1').textContent=path?path.split(/[\\/]/).at(-1):'E4B Core';if(!path){branchLabel.textContent='';worktreeButton.disabled=true;return}try{const response=await fetch('/workspace/info',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({path})});const info=await response.json();if(session!==id)return;branchLabel.textContent=info.branch?' · '+info.branch:'';worktreeButton.disabled=!info.git}catch{worktreeButton.disabled=true}}
worktreeButton.onclick=async()=>{if(busy||!cwd.value)return;worktreeButton.disabled=true;try{const response=await fetch('/workspace/worktree',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({path:cwd.value})});const info=await response.json();if(!response.ok)throw Error(info.error);openWorkspace(info.path)}catch(error){add('notice',error.message)}finally{refreshWorkspace()}};
const folderDialog=document.querySelector('#folder-dialog'),folderPath=document.querySelector('#folder-path'),folderList=document.querySelector('#folder-list');
let session=crypto.randomUUID(),busy=false,statusNode=null;
let pendingFiles=[],workQueue=[],completedTurns=0;
const terminals=new Map();
window.addEventListener('pagehide',()=>{if(busy)navigator.sendBeacon('/chat/cancel',JSON.stringify({session_id:session}));for(const id of terminals.keys())navigator.sendBeacon('/terminal/close',JSON.stringify({session_id:id}))});
const threads=new Map(),toolCards=new Map();
const review=document.querySelector('#review'),reviewFiles=document.querySelector('#review-files');const reviewButton=document.createElement('button');reviewButton.id='review-toggle';reviewButton.textContent='修改';document.querySelector('.actions').prepend(reviewButton);reviewButton.onclick=()=>review.hidden=!review.hidden;document.querySelector('#review-close').onclick=()=>review.hidden=true;
function rememberThread(){threads.set(session,{nodes:[...chat.childNodes],changes:[...reviewFiles.childNodes],cwd:cwd.value,title:threads.get(session)?.title||'新對話',draft:input.value,files:pendingFiles,effort:effort.value,agent:agent.checked,mode:mode.value});renderThreads()}
function renderThreads(){const list=document.querySelector('#threads');list.replaceChildren();for(const [id,thread] of threads){const button=document.createElement('button');button.className='thread'+(id===session?' active':'');button.textContent=(thread.cwd?thread.cwd.split(/[\\/]/).at(-1)+' · ':'')+thread.title;button.title=thread.cwd||thread.title;button.onclick=()=>{if(busy||id===session)return;rememberThread();session=id;cwd.value=thread.cwd;chat.replaceChildren(...thread.nodes);reviewFiles.replaceChildren(...thread.changes);document.querySelector('#review-empty').hidden=reviewFiles.childNodes.length>0;clearStatus();restoreDraft();renderThreads()};list.append(button)}}
function newThread(){if(busy)return;rememberThread();session=crypto.randomUUID();chat.replaceChildren();reviewFiles.replaceChildren();document.querySelector('#review-empty').hidden=false;input.value='';pendingFiles=[];renderFiles();refreshTerminal();add('notice','已開始新對話');rememberThread();input.focus()}
document.querySelector('#new-thread').onclick=newThread;
document.querySelector('#open-project').onclick=()=>document.querySelector('#browse').click();
document.querySelector('#stop').onclick=async()=>{workQueue=[];await fetch('/chat/cancel',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({session_id:session})});document.querySelector('#stop').disabled=true;add('notice','正在停止工作…')};
const terminalPane=document.querySelector('#terminal-pane'),terminalOutput=document.querySelector('#terminal-output');
const terminalButton=document.createElement('button');terminalButton.id='terminal-toggle';terminalButton.textContent='終端';document.querySelector('.actions').prepend(terminalButton);
function showTerminal(open){terminalPane.hidden=!open;document.querySelector('main').classList.toggle('terminal-open',open);refreshTerminal();if(open)document.querySelector('#terminal-command').focus()}
terminalButton.onclick=()=>showTerminal(terminalPane.hidden);
document.querySelector('#terminal-hide').onclick=()=>showTerminal(false);
function terminalState(id=session){if(!terminals.has(id))terminals.set(id,{output:'',cwd:cwd.value,history:[],index:0,busy:false});return terminals.get(id)}
function refreshTerminal(){const state=terminalState();terminalOutput.textContent=state.output;terminalOutput.scrollTop=terminalOutput.scrollHeight;document.querySelector('#terminal-cwd').textContent=state.cwd||cwd.value||'請先開啟專案';document.querySelector('#terminal-run').disabled=state.busy;document.querySelector('#terminal-stop').disabled=!state.busy}
document.querySelector('#terminal-clear').onclick=()=>{terminalState().output='';refreshTerminal()};
document.querySelector('#terminal-stop').onclick=async()=>{await fetch('/terminal/close',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({session_id:session})})};
async function consumeStream(response,onEvent){if(!response.ok)throw new Error(await response.text());const reader=response.body.getReader(),decoder=new TextDecoder();let pending='';while(true){const {value,done}=await reader.read();pending+=decoder.decode(value||new Uint8Array(),{stream:!done});const [blocks,rest]=eventBlocks(pending);pending=rest;for(const block of blocks){let type='message',data='{}';for(const line of block.split('\n')){if(line.startsWith('event: '))type=line.slice(7);if(line.startsWith('data: '))data=line.slice(6)}await onEvent(type,JSON.parse(data))}if(done)break}}
document.querySelector('#terminal-form').onsubmit=async event=>{event.preventDefault();const field=document.querySelector('#terminal-command'),command=field.value.trim(),id=session,state=terminalState(id);if(!command||state.busy)return;if(!cwd.value){state.output+='請先開啟專案。\n';refreshTerminal();return}field.value='';state.busy=true;state.output+='PS '+(state.cwd||cwd.value)+'> '+command+'\n';state.history.push(command);state.index=state.history.length;refreshTerminal();try{const response=await fetch('/terminal',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({session_id:id,command,working_dir:state.cwd||cwd.value})});await consumeStream(response,(type,data)=>{if(type==='delta')state.output+=data.text;else if(type==='done'){state.cwd=data.cwd;state.output+='[exit code: '+data.exit_code+']\n'}else if(type==='cancelled')state.output+='[已停止]\n';else if(type==='error')state.output+='錯誤：'+data.message+'\n';state.output=state.output.slice(-200000);if(session===id)refreshTerminal()})}catch(error){state.output+='錯誤：'+error.message+'\n'}finally{state.busy=false;if(session===id)refreshTerminal()}};
document.querySelector('#terminal-command').onkeydown=event=>{const state=terminalState();if(event.key==='ArrowUp'||event.key==='ArrowDown'){event.preventDefault();state.index=Math.max(0,Math.min(state.history.length,state.index+(event.key==='ArrowUp'?-1:1)));event.target.value=state.history[state.index]||''}};
function renderFiles(){const host=document.querySelector('#attachments');host.replaceChildren();for(const file of pendingFiles){const chip=document.createElement('button');chip.type='button';chip.className='attachment';chip.textContent=file.name+' ×';chip.onclick=()=>{pendingFiles=pendingFiles.filter(item=>item!==file);renderFiles()};host.append(chip)}}
document.querySelector('#attach').onclick=()=>document.querySelector('#file-input').click();
document.querySelector('#file-input').onchange=async event=>{try{const selected=[...event.target.files];if(pendingFiles.length+selected.length>8)throw Error('最多附加 8 個檔案');if([...pendingFiles,...selected].reduce((sum,file)=>sum+file.size,0)>2000000)throw Error('附件合計不得超過 2 MB');for(const file of selected){const bytes=new Uint8Array(await file.arrayBuffer());let binary='';for(let offset=0;offset<bytes.length;offset+=8192)binary+=String.fromCharCode(...bytes.subarray(offset,offset+8192));pendingFiles.push({name:file.name,data:btoa(binary),size:file.size})}renderFiles()}catch(error){add('notice',error.message)}finally{event.target.value=''}};
function restoreDraft(){const thread=threads.get(session);input.value=thread?.draft||'';pendingFiles=thread?.files||[];if(thread){effort.value=thread.effort;agent.checked=thread.agent;mode.value=thread.mode}cwdWrap.hidden=!agent.checked;renderFiles();refreshTerminal();refreshWorkspace();reviewButton.textContent='修改'+(reviewFiles.children.length?' · '+reviewFiles.children.length:'')}
rememberThread();
function add(kind,text){const node=document.createElement('div');node.className=(kind==='notice'?'notice':'msg '+kind);node.textContent=text;chat.append(node);chat.scrollTop=chat.scrollHeight;return node}
function eventBlocks(buffer){const blocks=buffer.split('\n\n');return [blocks.slice(0,-1),blocks.at(-1)]}
function clearStatus(){if(statusNode){statusNode.remove();statusNode=null}}
function renderAnswer(node){const raw=node.textContent;node.replaceChildren();let code=null;for(const line of raw.split('\n')){if(line.startsWith('```')){if(code){code=null}else{const pre=document.createElement('pre');code=document.createElement('code');pre.append(code);node.append(pre)}continue}if(code){code.textContent+=line+'\n';continue}const heading=line.match(/^(#{1,3})\s+(.*)/);const item=document.createElement(heading?'h'+(heading[1].length+1):'div');const source=heading?heading[2]:line;const tokens=source.split(/(`[^`]+`|\*\*[^*]+\*\*)/g);for(const token of tokens){const element=document.createElement(token.startsWith('`')?'code':token.startsWith('**')?'strong':'span');element.textContent=token.startsWith('`')?token.slice(1,-1):token.startsWith('**')?token.slice(2,-2):token;item.append(element)}if(!source)item.append(document.createElement('br'));node.append(item)}}
agent.addEventListener('change',()=>{cwdWrap.hidden=!agent.checked});
fetch('/config').then(response=>response.json()).then(value=>{effort.value=value.thinking_effort;agent.checked=value.agent;cwdWrap.hidden=!agent.checked}).catch(()=>{});
document.querySelector('#save').addEventListener('click',async()=>{if(busy)return;const response=await fetch('/config',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({thinking_effort:effort.value,agent:agent.checked})});if(!response.ok){add('notice','設定儲存失敗：'+await response.text());return}add('notice','Agent 與 thinking effort 設定已儲存')});
document.querySelector('#shutdown').addEventListener('click',async()=>{if(busy||!confirm('關閉 E4B 並釋放 GPU 記憶體？'))return;const response=await fetch('/shutdown',{method:'POST',headers:{'Content-Type':'application/json'},body:'{}'});if(!response.ok){add('notice','關閉失敗：'+await response.text());return}send.disabled=true;input.disabled=true;add('notice','E4B 已關閉；需要時再執行「開啟 E4B.cmd」')});
async function directoryInfo(path){const response=await fetch('/directories',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({path})});if(!response.ok){const value=await response.json().catch(()=>({}));throw new Error(value.error||'資料夾不存在')}return response.json()}
let folderRequest=0;
async function showDirectory(path,fallback=true){
  const request=++folderRequest,use=document.querySelector('#folder-use'),errorNode=document.querySelector('#folder-error');
  const address=document.querySelector('#folder-address'),previousAddress=address.value;
  use.disabled=true;delete folderPath.dataset.path;errorNode.hidden=true;folderList.setAttribute('aria-busy','true');
  try{
    let value;
    try{value=await directoryInfo(path)}catch(error){if(fallback&&path)value=await directoryInfo('');else throw error}
    if(request!==folderRequest||!folderDialog.open)return;
    folderPath.textContent=value.current;folderPath.dataset.path=value.current;
    if(document.activeElement!==address&&address.value===previousAddress)address.value=value.current;
    folderList.replaceChildren();
    if(value.parent){const up=document.createElement('button');up.className='folder-item';up.textContent='↰ 上一層';up.addEventListener('click',()=>showDirectory(value.parent,false));folderList.append(up)}
    for(const item of value.directories){const button=document.createElement('button');button.className='folder-item';button.textContent='📁 '+item.name;button.addEventListener('click',()=>showDirectory(item.path,false));folderList.append(button)}
    use.disabled=busy;
  }catch(error){
    if(request!==folderRequest||!folderDialog.open)return;
    errorNode.textContent='無法開啟資料夾：'+error.message;errorNode.hidden=false;
  }finally{if(request===folderRequest)folderList.setAttribute('aria-busy','false')}
}
document.querySelector('#browse').addEventListener('click',()=>{if(busy){add('notice','請先停止或等目前工作完成，再開啟資料夾。');return}folderDialog.showModal();showDirectory(cwd.value.trim())});
folderDialog.addEventListener('close',()=>{folderRequest++;document.querySelector('#folder-use').disabled=true;delete folderPath.dataset.path;folderList.setAttribute('aria-busy','false')});
document.querySelector('#folder-close').addEventListener('click',()=>folderDialog.close());
document.querySelector('#folder-address-form').onsubmit=event=>{event.preventDefault();showDirectory(document.querySelector('#folder-address').value.trim(),false)};
function openWorkspace(path){if(busy||typeof path!=='string'||!path)return;rememberThread();cwd.value=path;session=crypto.randomUUID();folderDialog.close();input.value='';pendingFiles=[];renderFiles();refreshTerminal();refreshWorkspace();chat.replaceChildren();reviewFiles.replaceChildren();document.querySelector('#review-empty').hidden=false;add('notice','已開啟 Workspace：'+cwd.value+'；這是新的對話 context');rememberThread()}
document.querySelector('#folder-use').addEventListener('click',()=>openWorkspace(folderPath.dataset.path));
async function approve(payload){
  const details=payload.preview||JSON.stringify(payload.arguments,null,2);
  const accepted=await new Promise(resolve=>{const card=document.createElement('section');card.className='approval-card';const title=document.createElement('strong');title.textContent='需要批准 · '+payload.tool;const pre=document.createElement('pre');pre.textContent=details;card.append(title,pre);for(const [label,value] of [['允許這次操作',true],['拒絕',false]]){const button=document.createElement('button');button.textContent=label;if(!value)button.className='secondary';button.onclick=()=>{card.replaceChildren(title);title.textContent=value?'已批准 · '+payload.tool:'已拒絕 · '+payload.tool;resolve(value)};card.append(button)}chat.append(card);card.scrollIntoView({block:'nearest'});document.querySelector('#stop').addEventListener('click',()=>resolve(false),{once:true})});
  const response=await fetch('/chat/approve',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({session_id:session,call_id:payload.call_id,approved:accepted})});
  if(!response.ok)throw new Error(await response.text());
}
async function handleEvent(type,payload,answer){
  if(type==='delta'){clearStatus();answer.textContent+=payload.text;chat.scrollTop=chat.scrollHeight}
  else if(type==='status'){clearStatus();statusNode=add('notice',payload.message)}
  else if(type==='compacted'){add('notice',payload.message)}
  else if(type==='approval'){clearStatus();await approve(payload);statusNode=add('notice','等待 Agent 繼續…')}
  else if(type==='tool'){clearStatus();let card=toolCards.get(payload.call_id);if(payload.phase==='running'){card=document.createElement('details');card.className='tool-card';const title=document.createElement('summary');title.textContent='執行中 · '+payload.tool;const pre=document.createElement('pre');pre.textContent=JSON.stringify(payload.arguments,null,2);card.append(title,pre);chat.append(card);toolCards.set(payload.call_id,card)}else if(card){card.querySelector('summary').textContent='已結束 · '+payload.tool;const pre=document.createElement('pre');pre.textContent=payload.result;card.append(pre)}}
  else if(type==='cancelled'){clearStatus();add('notice','工作已停止')}
  else if(type==='done'){completedTurns++}
  else if(type==='change'){document.querySelector('#review-empty').hidden=true;let card=[...reviewFiles.children].find(node=>node.dataset.path===payload.path);if(!card){card=document.createElement('details');card.dataset.path=payload.path;reviewFiles.append(card)}card.replaceChildren();const title=document.createElement('summary');title.textContent=payload.path;const pre=document.createElement('pre');for(const line of payload.diff.split('\n')){const span=document.createElement('span');span.textContent=line+'\n';if(line.startsWith('+'))span.className='diff-add';if(line.startsWith('-'))span.className='diff-remove';pre.append(span)}card.append(title,pre);reviewButton.textContent='修改 · '+reviewFiles.children.length}
  else if(type==='error'){throw new Error(payload.message)}
}
async function ask(text,attachments=[]){
  busy=true;
  const restoreInput=()=>{busy=false;input.value=text;pendingFiles=attachments;renderFiles()};
  if(agent.checked&&!cwd.value.trim()){restoreInput();add('notice','請先按「開啟資料夾」選擇這次要使用的 Workspace。');return}
  if(agent.checked){try{await directoryInfo(cwd.value.trim())}catch(error){restoreInput();add('notice','Workspace 無效：'+error.message+'；請重新開啟資料夾。');return}}
  busy=true;send.disabled=false;send.textContent='＋';send.setAttribute('aria-label','排入下一輪');document.querySelector('#stop').hidden=false;document.querySelector('#stop').disabled=false;document.querySelector('#welcome')?.remove();if(threads.get(session)?.title==='新對話'){threads.get(session).title=text.slice(0,28);renderThreads()}add('user',text+(attachments.length?'\n📎 '+attachments.map(file=>file.name).join('、'):''));const answer=add('assistant','');
  try{
    const body={session_id:session,text,attachments,thinking_effort:effort.value,agent:agent.checked,plan:mode.value==='plan',working_dir:cwd.value.trim()};
    const response=await fetch('/chat',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(body)});if(!response.ok)throw new Error(await response.text());
    await consumeStream(response,(type,payload)=>handleEvent(type,payload,answer));
    clearStatus();if(!answer.textContent)answer.remove();else renderAnswer(answer);
  }catch(error){clearStatus();answer.textContent='錯誤：'+error.message}
  finally{busy=false;send.disabled=false;send.textContent='↑';send.setAttribute('aria-label','送出');document.querySelector('#stop').hidden=true;rememberThread();input.focus();if(workQueue.length){const next=workQueue.shift();ask(next.text,next.attachments)}}
}
document.querySelector('#form').addEventListener('submit',event=>{event.preventDefault();const text=input.value.trim()||(pendingFiles.length?'分析附件':'');if(!text)return;const attachments=pendingFiles;pendingFiles=[];input.value='';renderFiles();if(busy){workQueue.push({text,attachments});add('notice','已排入下一輪工作 · 待處理 '+workQueue.length+' 項')}else ask(text,attachments)});
input.addEventListener('keydown',event=>{if(event.key==='Enter'&&!event.shiftKey){event.preventDefault();document.querySelector('#form').requestSubmit()}});
document.querySelector('#reset').addEventListener('click',newThread);
</script></body></html>"""
